&Title = 'Relatório de Compra de Produtos' &AppName = 'Sistema de Gestão de Alimentação Escolar' &numeroLinha = 0 &Page = 0 &situacao = '' LoadWWPContext.Call(&WWPContext) &prefCodigo = &WWPContext.prefCodigo
For each trnsnota, trnsnotaitens, trnsprodutos order notaData, notaCodigo, notaItemProdutoDescricao when &ordem = 'N' order notaData, notaCodigo, notaItemProduto when &ordem = 'C' where prodCodigo = notaItemProduto where prefCodigo = &prefCodigo where notaData >= &dataIncial when not &dataIncial.IsEmpty() where notaData <= &dataFinal when not &dataFinal.IsEmpty() where notaItemProduto = &prodCodigo when &prodCodigo<>0 where prodTipo = &buscarGrupo when &buscarGrupo<>0 where notaFornecedor = &forCodigo when &forCodigo<>0 // where notaStatus = 'A'
Do 'Cabecalho' /* if &prodCodigo<>0 if &totalizacao = 'S' print PrintTotalProduto endif else if &totalQuantidade<>0 if &totalizacao = 'S' print PrintTotalProduto &numeroLinha +=1 Do 'Cabecalho' endif &totalQuantidade = 0 &valorTotalProduto = 0 endif endif */ &prodDescricao = notaItemProduto.ToString().Trim() +' - '+ notaItemProdutoDescricao &unidSigla = PRCDBuscarDescricaoSiglaOuUnidade(&prefCodigo, notaItemProdutoUnidade, 'S')
// totalizando a quantidade &distItemQuantidade = notaItemQtde &totalQuantidade += notaItemQtde
// totalizando os valores &valorProduto = notaItemValor.ToString() &valorTotal = notaItemValor*notaItemQtde &valorTotalProduto += &valorTotal if notaStatus = 'A' &situacao = 'Ativa' &distItemPesoTotal += notaItemQtde &valorTotalGeral += &valorTotal else if notaStatus = 'I' &situacao = 'Inativo' else &situacao = 'Cancelada' endif endif print printDados &numeroLinha +=1
endFor
/* if &totalQuantidade<>0 if &totalizacao = 'S' print PrintTotalProduto endif endif */
if &totalizacao = 'S' print TotalGeral endif
sub 'Cabecalho' if &numeroLinha=0 or &numeroLinha>=23 For each where prefCodigo = &prefCodigo &prefLogo = prefLogo print printCabecalho print printCabecalhoDados endFor &numeroLinha=1 endif endSub
